package com.nexuspc.catalog.product;
import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
import org.springframework.data.repository.query.Param;
import org.springframework.data.jpa.repository.Query;
import java.util.List; import org.springframework.data.repository.query.Param; import java.util.*;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.Lock;
public interface ProductRepository extends JpaRepository<Product,Long>{@Query("select p from Product p where p.slug=:slug and (p.active=true or p.active is null)") Optional<Product> findBySlug(@Param("slug") String slug); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select p from Product p where p.id=:id") Optional<Product> findLockedById(@Param("id") Long id); boolean existsBySlug(String slug); boolean existsBySku(String sku); @Query("select p from Product p where (p.active=true or p.active is null) and (:q is null or lower(p.name) like lower(concat('%',:q,'%')) or lower(p.description) like lower(concat('%',:q,'%')) or lower(p.brand) like lower(concat('%',:q,'%'))) and (:category is null or p.category.slug=:category) and (:featured=false or p.featured=true) and (:bestseller=false or p.bestseller=true) and (:newProduct=false or p.newProduct=true) and (:minPrice is null or p.price>=:minPrice) and (:maxPrice is null or p.price<=:maxPrice) and (:brand is null or lower(p.brand)=lower(:brand))") org.springframework.data.domain.Page<Product> search(@Param("q")String q,@Param("category")String category,@Param("featured")boolean featured,@Param("bestseller")boolean bestseller,@Param("newProduct")boolean newProduct,@Param("minPrice")java.math.BigDecimal minPrice,@Param("maxPrice")java.math.BigDecimal maxPrice,@Param("brand")String brand,org.springframework.data.domain.Pageable pageable); @Query("select count(p) from Product p where p.category.id=:id and (p.active=true or p.active is null)") long countByCategoryId(@Param("id") Long id); @Query("select p.category.id, count(p) from Product p where p.active=true or p.active is null group by p.category.id") List<Object[]> countByCategoryIds();}
